#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long w, m;
    cin >> w >> m;
    if (w <= 3) {
        cout << "YES\n";
        return 0;
    }
    int nDigits = 0;
    long long val = 1;
    vector<long long> bases(100);
    while (val <= 2e9) {
        bases[nDigits] = val;
        val *= w;
        nDigits++;
    }
    vector<int> values(nDigits, -1);
    long long curTotal = 0;
    for (int i = 0; i < nDigits; i++) {
        curTotal -= bases[i];
    }
    bool works = false;
    outer:
    while (true) {
        int index = 0;
        while (true) {
            values[index]++;
            curTotal += bases[index];

            if (values[index] != 2) {
                if (abs(curTotal) == m) {
                    works = true;
                }
                break;
            }
            values[index] = -1;
            curTotal -= bases[index] * 3;
            index++;
            if (index == nDigits) break outer;
        }
    }
    cout << (works ? "YES" : "NO") << "\n";
    return 0;
}

